export type LpMonitorTriggerType = 'manual' | 'manual_notify' | 'scheduled';
export type LpMonitorRunStatus = 'running' | 'completed' | 'failed' | 'skipped';
export type LpMonitorWebhookKind = 'lark' | 'custom';

export interface LpMonitorIssue {
  ruleId?: string;
  ruleLabel?: string;
  chain?: string;
  dexName?: string;
  poolId?: string;
  poolName?: string;
  tokenId?: string;
  message?: string;
  curPriceRatioBounds?: number[];
  lpInUsd?: number | null;
  positionValueUsd?: number | null;
  [key: string]: unknown;
}

export interface LpMonitorRunPayload {
  owner: string;
  positionCount?: number;
  checkedCount: number;
  issueCount: number;
  elapsedMs: number;
  chainStats?: Array<{
    chain: string;
    positionCount: number;
    issueCount: number;
    error?: string;
  }>;
  issueStats: Array<{
    ruleId: string;
    ruleLabel: string;
    count: number;
  }>;
  runtimeErrors?: Array<Record<string, unknown>>;
  issues: LpMonitorIssue[];
}

export interface LpMonitorPersistedSummary {
  [key: string]: unknown;
  status: LpMonitorRunStatus;
  triggerType: LpMonitorTriggerType;
  startedAt: string;
  completedAt?: string;
  updatedAt: string;
  scheduledIntervalHours: number;
  owner: string;
  positionCount?: number;
  checkedCount?: number;
  issueCount?: number;
  elapsedMs?: number;
  chainStats?: Array<Record<string, unknown>>;
  issueStats?: Array<Record<string, unknown>>;
  runtimeErrors?: Array<Record<string, unknown>>;
  issuesPreview?: Array<Record<string, unknown>>;
  notified?: boolean;
  notifyWarning?: string;
  error?: string;
}

export interface BuildLpMonitorPersistedSummaryParams {
  payload: LpMonitorRunPayload;
  status: LpMonitorRunStatus;
  triggerType: LpMonitorTriggerType;
  startedAt: string;
  completedAt: string;
  notified?: boolean;
  notifyWarning?: string;
  error?: string;
}

export interface BuildLpMonitorAlertWebhookBodyParams {
  webhookKind: LpMonitorWebhookKind;
  payload: Pick<LpMonitorRunPayload, 'owner' | 'checkedCount' | 'issueCount' | 'elapsedMs' | 'issueStats' | 'issues'> & {
    positionCount?: number;
    targetCount?: number;
  };
  chainLabelResolver?: (chain: string) => string;
}

export const LP_MONITOR_OUTPUT_MARKER: '__OMNIX_MONITOR_RESULT__';
export const LP_MONITOR_SCHEDULE_INTERVAL_HOURS: 2;
export const LP_MONITOR_ISSUE_PREVIEW_LIMIT: 12;

export function parseLpMonitorPayload(output: string): LpMonitorRunPayload | null;
export function buildLpMonitorPersistedSummary(
  params: BuildLpMonitorPersistedSummaryParams
): LpMonitorPersistedSummary;
export function buildLpMonitorAlertWebhookBody(
  params: BuildLpMonitorAlertWebhookBodyParams
): Record<string, unknown>;
